package com.netshield.api.integration;

/**
 * Extension point for external systems (router, DNS filter, WireGuard, Wazuh/Suricata, threat intel, LLM).
 * No real implementation exists yet. Each kind is bound to {@link Unconfigured}, which reports NOT_CONFIGURED and
 * performs no action. Real adapters must be read-only by default, require explicit user configuration, and must never
 * execute commands generated by an LLM.
 */
public interface IntegrationAdapter {
    enum Kind { ROUTER, DNS_FILTER, WIREGUARD, WAZUH_SURICATA, THREAT_INTEL, LLM }
    enum Status { NOT_CONFIGURED, CONNECTED, ERROR }

    Kind kind();
    String displayName();
    Status status();
    /** What the user must provide before this can work, in plain language. */
    String requirement();

    record Unconfigured(Kind kind, String displayName, String requirement) implements IntegrationAdapter {
        @Override public Status status() { return Status.NOT_CONFIGURED; }
    }
}
